// The ground under the plate is a gradients.sh palette: "mesh" (blue family,
// sits with the accent) for dark, "pixel-glass" for light. `tint` is the line
// while it is seen through the counters, `ink` once it is uncovered.
const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    ink: "#F5F4F0",
    tint: "#0A0F33",
    grain: 0.07,
    ground: "#0a0d24",
    blobs: [
      ["#ecdcf2", 86, 94, 30],
      ["#2e45b7", 16, 20, 100],
      ["#8796ee", 84, 22, 62],
      ["#0e1645", 20, 86, 100],
      ["accent", 52, 50, 58],
    ],
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    ink: "#121214",
    tint: "#2B1D6E",
    grain: 0.045,
    ground: "#f4f3f1",
    blobs: [
      ["#7a3cff", 18, 24, 78],
      ["#ff4fb8", 84, 28, 62],
      ["#3d6bff", 72, 88, 82],
      ["accent", 24, 82, 50],
    ],
  },
} as const;

const counterRevealDuration = EXIT + EXIT_LEN + 40;

function advance(ch: string) {
  const code = ch.charCodeAt(0);
  return (code >= 32 && code < 127 ? SORA_500[code - 32] : 640) / 1000;
}

function layoutRow(text: string, track: number) {
  const chars = Array.from(text);
  const xs: number[] = [];
  let x = 0;
  chars.forEach((ch, i) => {
    xs.push(x);
    const a = ch === " " ? WORD_SPACE : advance(ch);
    x += a + (i < chars.length - 1 ? track : 0);
  });
  return { chars, xs, width: x };
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={29}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function CounterRevealBase({
  word = "Beta",
  line = "Out now.",
  accent = "#3B5BFD",
  ink,
  background,
  fontFamily = sora,
  stagger = STAGGER,
  liftAt = EXIT,
  scale = 1,
  delay = 0,
  grain = true,
  theme = "dark",
  speed = 1,
}: CounterRevealProps) {
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H } = useSceneConfig();
  const c = THEMES[theme];
  const fg = ink ?? c.ink;
  const wordInk = ink ?? c.fg;
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");

  const front = useMemo(() => layoutRow(word, WORD_TRACK), [word]);
  const back = useMemo(() => layoutRow(line, LINE_TRACK), [line]);

  // Front word fills the frame edge to edge.
  const F = Math.min((W * 0.96) / front.width, (H * 0.66) / CAP);
  const wordLeft = W / 2 - (front.width * F) / 2;
  const baseline = H / 2 + (CAP * F) / 2;

  // Back line at poster size; while it hides behind the windows it is set
  // much larger and darker, so its strokes register inside the counters.
  const B = Math.min((W * 0.86) / back.width, (H * 0.34) / CAP);
  const lineLeft = W / 2 - (back.width * B) / 2;
  const lineBase = H / 2 + (CAP * B) / 2;
  const end = liftAt + EXIT_LEN;
  const lineAt = (f: number) => {
    const drift = EASE_IO(interpolate(f, [0, end], [0, 1], CLAMP));
    const shrink = EASE_IO(
      interpolate(f, [liftAt - 6, end + 4], [0, 1], CLAMP),
    );
    const settle = interpolate(f, [end, end + 36], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    return {
      shift: (1 - drift) * W * 0.45,
      scale: (1.9 - 0.9 * shrink) * (1 + 0.03 * settle),
    };
  };
  const { shift: lineShift, scale: lineScale } = lineAt(t);
  // The back line is SVG text placed by attributes, so its drawing carries
  // the mark. It counts as moving while the line still moves a thousandth of
  // a pixel, and also once it holds at 1.03: the lean only stays on a drawing
  // that moves, and dropping it there would snap the resting line to the
  // nearest pixel.
  const lineStep = (f: number) => {
    const a = lineAt(f);
    return (
      Math.abs(a.shift - lineShift) + Math.abs(a.scale - lineScale) * (W / 2)
    );
  };
  const lineMoving =
    lineStep(t + speed) > 1e-3 || lineStep(t - speed) > 1e-3 || lineScale !== 1;
  const tint = c.tint;
  // Blobs drift a few percent over the shot, deterministic in frame.
  const flow = interpolate(t, [0, counterRevealDuration], [0, 1], CLAMP);
  const ground = [
    ...c.blobs.map(([col, x, y, a], i) => {
      const dx = (i % 2 ? -5 : 5) * flow;
      const dy = (i % 3 === 0 ? 4 : -3) * flow;
      const cc = col === "accent" ? accent : col;
      return `radial-gradient(85% 95% at ${x + dx}% ${y + dy}%, color-mix(in oklab, ${cc} ${a}%, transparent) 0%, transparent 68%)`;
    }),
    c.ground,
  ].join(", ");

  const exit = EASE_IO(interpolate(t, [liftAt, end], [0, 1], CLAMP));
  const plateY = -exit * H * 1.04;
  const push = 1 + 0.025 * interpolate(t, [ENTER_LEN, liftAt], [0, 1], CLAMP);
  // Screen y of the plate's trailing edge: below it the line is already
  // uncovered and shows in its final ink; through the windows it stays dark.
  const edgeY = plateY + baseline + (H - baseline) * push;

  const rise = (i: number) =>
    EASE_OUT(
      interpolate(
        t,
        [ENTER + i * stagger, ENTER + i * stagger + ENTER_LEN],
        [0, 1],
        CLAMP,
      ),
    );
  const glyphAt = (i: number) =>
    `translate(${wordLeft + front.xs[i] * F} ${baseline + (1 - rise(i)) * CAP * F * 1.08}) scale(${F / 1000})`;

  const maskId = `m${uid}`;
  const clipId = `c${uid}`;
  const edgeId = `e${uid}`;
  // Holes in the plate overshoot by a hair; the glyph drawn on top hides it.
  const pad = (Math.max(1.5, 0.004 * F) * 1000) / F;

  return (
    <AbsoluteFill
      style={{
        background:
          background === "transparent"
            ? "transparent"
            : (background ?? c.ground),
        overflow: "hidden",
      }}
    >
      {background === undefined ? (
        <div style={{ position: "absolute", inset: 0, background: ground }} />
      ) : null}
      <ScaleLayer scale={scale}>
        <svg
          width={W}
          height={H}
          viewBox={`0 0 ${W} ${H}`}
          style={{
            position: "absolute",
            inset: 0,
            transform: glide(lineMoving),
          }}
          aria-hidden
        >
          <defs>
            <clipPath id={clipId}>
              <rect
                x={-W}
                y={-H}
                width={W * 3}
                height={H + baseline + 0.02 * F}
              />
            </clipPath>
            <clipPath id={edgeId}>
              <rect x={0} y={edgeY} width={W} height={Math.max(0, H - edgeY)} />
            </clipPath>
            <mask id={maskId} maskUnits="userSpaceOnUse">
              <rect x={-W} y={-H} width={W * 3} height={H * 3} fill="white" />
              <g clipPath={`url(#${clipId})`}>
                {front.chars.map((ch, i) => {
                  const g = GLYPHS[ch];
                  if (!g?.holes) return null;
                  return (
                    <path
                      key={`${i}-${ch}`}
                      d={g.holes}
                      fill="black"
                      stroke="black"
                      strokeWidth={pad}
                      strokeLinejoin="round"
                      transform={glyphAt(i)}
                    />
                  );
                })}
              </g>
            </mask>
          </defs>

          <g
            transform={`translate(${W / 2 + lineShift} ${H / 2}) scale(${lineScale}) translate(${-W / 2} ${-H / 2})`}
          >
            <text
              x={back.xs.map((x) => lineLeft + x * B).join(" ")}
              y={lineBase}
              fontFamily={fontFamily}
              fontWeight={500}
              fontSize={B}
              fill={tint}
              style={{ fontOpticalSizing: "none" }}
            >
              {back.chars.join("")}
            </text>
          </g>

          <g transform={`translate(0 ${plateY})`}>
            <g
              transform={`translate(${W / 2} ${baseline}) scale(${push}) translate(${-W / 2} ${-baseline})`}
            >
              <rect
                x={-W}
                y={-H}
                width={W * 3}
                height={H * 2}
                fill={c.bg}
                mask={`url(#${maskId})`}
              />
              <g clipPath={`url(#${clipId})`} fill={wordInk}>
                {front.chars.map((ch, i) => {
                  const g = GLYPHS[ch];
                  if (g) {
                    return (
                      <path
                        key={`${i}-${ch}`}
                        d={g.outer + g.holes}
                        fillRule="evenodd"
                        transform={glyphAt(i)}
                      />
                    );
                  }
                  return (
                    <text
                      key={`${i}-${ch}`}
                      transform={glyphAt(i)}
                      fontFamily={fontFamily}
                      fontWeight={500}
                      fontSize={1000}
                      style={{ fontOpticalSizing: "none" }}
                    >
                      {ch}
                    </text>
                  );
                })}
              </g>
            </g>
          </g>
          <g clipPath={`url(#${edgeId})`}>
            <g
              transform={`translate(${W / 2 + lineShift} ${H / 2}) scale(${lineScale}) translate(${-W / 2} ${-H / 2})`}
            >
              <text
                x={back.xs.map((x) => lineLeft + x * B).join(" ")}
                y={lineBase}
                fontFamily={fontFamily}
                fontWeight={500}
                fontSize={B}
                fill={fg}
                style={{ fontOpticalSizing: "none" }}
              >
                {back.chars.join("")}
              </text>
            </g>
          </g>
        </svg>
      </ScaleLayer>
      {grain ? <Grain opacity={c.grain} /> : null}
    </AbsoluteFill>
  );
}

