} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","word","line","stagger","liftAt","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  word: "Beta",
  line: "Out now.",
  stagger: 3,
  liftAt: 66,
  fontFamily: "Sora",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type CounterRevealElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof CounterRevealBase>;

const CounterRevealInner = forwardRef<
  HTMLDivElement,
  CounterRevealElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<CounterReveal>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <CounterRevealBase
          {...(componentProps as unknown as ComponentProps<typeof CounterRevealBase>)}
        />
      </div>
    </Sequence>
  );
});

export const CounterReveal = Interactive.withSchema({
  Component: CounterRevealInner,
  componentName: "<CounterReveal>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
